// Cloudflare Workers entry: wraps the OpenNext-generated worker and adds a
// Cron Trigger handler for the sweeper (the in-process 5-min setInterval from
// the VPS era cannot run on Workers).
// @ts-ignore -- generated by `opennextjs-cloudflare build` (untyped JS)
import worker from "./.open-next/worker.js";
import { sweeperTick } from "./lib/sweeper";

export default worker;

export async function scheduled(): Promise<void> {
  const result = await sweeperTick();
  console.log(
    `cron sweep: expiredLinks=${result.expiredLinks} pastesPurged=${result.pastesPurged}`,
  );
}
